INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24002','fiesta','Semana Santa de Alcalá la Real','Declarada de Interés Turístico Autonómico. Procesiones con siglos de historia por las empinadas calles del casco histórico.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','fiesta','Romería Virgen de la Cabeza','La mayor romería de España con más de 1 millón de personas. Se celebra el último domingo de abril en el Santuario del Cerro del Cabezo. 800 años de historia.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24062','fiesta','Fiesta de la Aceituna','Celebración de la cosecha de la aceituna en diciembre. Molinos en funcionamiento, degustaciones y cultura del aceite en vivo.','turismo');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19009','fiesta','Día de la Cruz','El 3 de mayo toda Granada se llena de cruces engalanadas con flores. Música, baile y concursos de cruces en patios, plazas y calles.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16012','fiesta','Feria del Caballo de Jerez','La feria más elegante de España. Caballos de pura raza española, flamenco, manzanilla y vestidos de flamenca por doquier durante una semana.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40018','fiesta','Feria de Abril de Sevilla','La fiesta más grande de España: 1 millón de visitas en 7 días. Casetas, sevillanas, caballos y trajes de flamenca.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40018','fiesta','Semana Santa de Sevilla','La más famosa del mundo. 60 hermandades, 100.000 costaleros y nazarenos, vistas en 180 países.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17008','fiesta','Fiesta de los Patios Cordobeses','Patrimonio Inmaterial de la Humanidad. Cada mayo los patios privados se abren al público rebosantes de flores y plantas.','UNESCO');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32019','fiesta','Corrida Goyesca de Ronda','Celebrada en septiembre con trajes de época goyesca. Una de las corridas más elegantes y fotografiadas del mundo.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33014','fiesta','Sanfermines','La fiesta más famosa del mundo: 7 al 14 de julio. El encierro de toros por las calles, exportado a la cultura popular global por Hemingway.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45015','fiesta','Las Fallas de Valencia','Patrimonio Inmaterial de la Humanidad. 800 monumentos de cartón y madera de hasta 30m que se queman en la noche del 19 de marzo.','UNESCO');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40003','fiesta','Semana Santa de Carmona','Declarada de Interés Turístico Nacional. Cofradías con siglos de historia en una ciudad amurallada medieval.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21011','fiesta','Alarde de Hondarribia','Desfile militar histórico que conmemora el levantamiento del sitio de 1638. Declarado de Interés Turístico Nacional.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24060','fiesta','Semana Santa de Mancha Real','Declarada de Interés Turístico Autonómico. Cofradías con tallas barrocas del s.XVII. Ambiente recogido de pueblo andaluz.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','fiesta','Moros y Cristianos de Alcoy','La fiesta de Moros y Cristianos más antigua y espectacular de España, desde 1276. Declarada de Interés Turístico Internacional.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31004','fiesta','Fiestas de la Vera Cruz','Los Caballos del Vino bajan a toda velocidad hasta el castillo. Declaradas de Interés Turístico Nacional.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','fiesta','Día de la Cruz','El 3 de mayo toda Granada se llena de cruces engalanadas con flores. Música, baile y concursos de cruces en patios, plazas y calles.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23058','fiesta','Semana Santa de Mancha Real','Declarada de Interés Turístico Autonómico. Cofradías con tallas barrocas del s.XVII. Ambiente recogido de pueblo andaluz.','turismo.gob.es');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','fiesta','Fiesta de la Aceituna','Celebración de la cosecha de la aceituna en diciembre. Molinos en funcionamiento, degustaciones y cultura del aceite en vivo.','turismo');
INSERT INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','fiesta','Corrida Goyesca de Ronda','Celebrada en septiembre con trajes de época goyesca. Una de las corridas más elegantes y fotografiadas del mundo.','turismo.gob.es');
